-- Junior middle school official learning resource seed.
-- Official resources use knowledge-point search pages instead of broad subject search pages.
-- Safe to run repeatedly: existing resources are updated by resource_name + subject, missing resources are inserted.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE IF NOT EXISTS tmp_junior_resource_seed (
    resource_name VARCHAR(200) NOT NULL,
    resource_type TINYINT NOT NULL,
    subject VARCHAR(50) NULL,
    knowledge_point VARCHAR(255) NULL,
    textbook_version VARCHAR(100) NULL,
    file_url VARCHAR(500) NULL,
    file_size BIGINT NULL,
    status TINYINT NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

TRUNCATE TABLE tmp_junior_resource_seed;

