UPDATE learning_resource r
JOIN tmp_junior_resource_seed s
  ON r.resource_name = s.resource_name
 AND r.subject = s.subject
SET r.resource_type = s.resource_type,
    r.knowledge_point = s.knowledge_point,
    r.textbook_version = s.textbook_version,
    r.file_url = s.file_url,
    r.file_size = s.file_size,
    r.status = s.status,
    r.update_time = NOW();

INSERT INTO learning_resource
(resource_name, resource_type, subject, knowledge_point, textbook_version, file_url, file_size, status, create_time, update_time)
SELECT s.resource_name, s.resource_type, s.subject, s.knowledge_point, s.textbook_version, s.file_url, s.file_size, s.status, NOW(), NOW()
FROM tmp_junior_resource_seed s
WHERE NOT EXISTS (
    SELECT 1 FROM learning_resource r
    WHERE r.resource_name = s.resource_name
      AND r.subject = s.subject
);

SELECT subject, COUNT(*) AS resource_count
FROM learning_resource
WHERE subject IN ('语文','数学','英语','物理','化学','生物','历史','地理','道德与法治')
GROUP BY subject
ORDER BY FIELD(subject, '语文','数学','英语','物理','化学','生物','历史','地理','道德与法治');

DROP TEMPORARY TABLE IF EXISTS tmp_junior_resource_seed;


-- Junior middle school exam-style demo question bank seed.
-- 9 subjects x 240 questions = 2160 questions.
-- English questions use English stems/options; other subjects use junior-exam style Chinese stems.
-- Safe to run repeatedly: existing questions are skipped by subject + question_text.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TEMPORARY TABLE IF NOT EXISTS tmp_junior_question_seed (
    subject VARCHAR(50) NOT NULL,
    knowledge_point VARCHAR(255) NULL,
    difficulty TINYINT NOT NULL,
    question_type TINYINT NOT NULL,
    question_text TEXT NOT NULL,
    options TEXT NULL,
    answer TEXT NULL,
    analysis TEXT NULL,
    scoring_points TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

TRUNCATE TABLE tmp_junior_question_seed;

-- Replace the junior demo question bank completely so old template questions cannot appear in exams.
-- question_bank foreign keys use ON DELETE CASCADE, so old answer/wrong-question rows for these demo questions are removed too.
DELETE FROM question_bank WHERE subject IN ('语文','数学','英语','物理','化学','生物','历史','地理','道德与法治');

