INSERT INTO question_bank
(subject, knowledge_point, difficulty, question_type, question_text, options, answer, analysis, scoring_points, create_time, update_time)
SELECT s.subject, s.knowledge_point, s.difficulty, s.question_type, s.question_text, s.options, s.answer, s.analysis, s.scoring_points, NOW(), NOW()
FROM tmp_junior_question_seed s
WHERE NOT EXISTS (
    SELECT 1 FROM question_bank q
    WHERE q.subject = s.subject AND q.question_text = s.question_text
);

SELECT subject, COUNT(*) AS question_count
FROM question_bank
WHERE subject IN ('语文','数学','英语','物理','化学','生物','历史','地理','道德与法治')
GROUP BY subject
ORDER BY FIELD(subject, '语文','数学','英语','物理','化学','生物','历史','地理','道德与法治');

DROP TEMPORARY TABLE IF EXISTS tmp_junior_question_seed;


