-- Subjective AI scoring and manual review demo data.
-- Purpose: verify AI scoring observability, pending manual review, and review completion flows.
-- Usage:
--   mysql --default-character-set=utf8mb4 -uroot -proot smart_learning_system < docs/sql/02_seed_data.sql

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

INSERT INTO sys_user (username, password, real_name, role, grade, subject, phone, status)
VALUES (
    'subjective_demo',
    '$2b$10$mviszuhf.i3jEjc2BrSJS.U0BLm2i7J5oNqWrUchDxqYgfHsgKRW.',
    'Subjective Review Demo',
    1,
    '八年级',
    '数学',
    NULL,
    1
)
ON DUPLICATE KEY UPDATE
    real_name = VALUES(real_name),
    role = VALUES(role),
    grade = VALUES(grade),
    subject = VALUES(subject),
    status = VALUES(status),
    update_time = CURRENT_TIMESTAMP;

INSERT INTO question_bank
(subject, knowledge_point, difficulty, question_type, question_text, options, answer, analysis, scoring_points, create_time, update_time)
SELECT
    '数学',
    '一次函数',
    2,
    4,
    '说明一次函数 y=kx+b 中 k 和 b 对图像的影响。',
    '',
    'k 决定直线的倾斜方向和陡峭程度，b 决定直线与 y 轴的交点。',
    '主观题重点看是否说明 k 的斜率作用，以及 b 的截距作用。',
    '说明 k 决定斜率或倾斜方向\n说明 b 决定 y 轴截距\n能结合 y=kx+b 的图像表达',
    NOW(),
    NOW()
WHERE NOT EXISTS (
    SELECT 1 FROM question_bank WHERE question_text = '说明一次函数 y=kx+b 中 k 和 b 对图像的影响。'
);

INSERT INTO assessment
(user_id, assessment_type, subject, knowledge_scope, difficulty, total_score, user_score, assessment_status, start_time, end_time, create_time, update_time)
SELECT
    u.user_id,
    2,
    '数学',
    '一次函数',
    2,
    100.00,
    42.00,
    2,
    DATE_SUB(NOW(), INTERVAL 20 MINUTE),
    NOW(),
    NOW(),
    NOW()
FROM sys_user u
WHERE u.username = 'subjective_demo'
  AND NOT EXISTS (
      SELECT 1 FROM assessment a
      WHERE a.user_id = u.user_id
        AND a.subject = '数学'
        AND a.knowledge_scope = '一次函数'
        AND a.assessment_type = 2
        AND a.create_time >= DATE_SUB(NOW(), INTERVAL 1 DAY)
  );

INSERT INTO assessment_answer
(assessment_id, user_id, question_id, user_answer, correct_answer, is_correct, score, max_score,
 score_status, review_status, review_comment, scoring_detail, ai_score, ai_confidence,
 scoring_points_snapshot, question_use_seconds, create_time, update_time)
SELECT
    a.assessment_id,
    u.user_id,
    q.question_id,
    'k 会影响线的方向，b 好像和位置有关，但没有说明和 y 轴交点的关系。',
    q.answer,
    0,
    42.00,
    100.00,
    2,
    0,
    '',
    'AI semantic scoring pending manual review, aiObservation=provider=rule_fallback; model=qwen3.7-max; latencyMs=0; failureCategory=invalid_response; errorCode=MODEL_JSON_PARSE_FAILED',
    42.00,
    45.00,
    q.scoring_points,
    95,
    NOW(),
    NOW()
FROM sys_user u
JOIN assessment a ON a.user_id = u.user_id
JOIN question_bank q ON q.question_text = '说明一次函数 y=kx+b 中 k 和 b 对图像的影响。'
WHERE u.username = 'subjective_demo'
  AND NOT EXISTS (
      SELECT 1 FROM assessment_answer aa
      WHERE aa.assessment_id = a.assessment_id
        AND aa.question_id = q.question_id
  );
